import type { Nuxt } from '@nuxt/schema'
import { addPermission, addRole, setDefaultRoles } from '@frigear-nu/auth/utils'
import OAuthServerModule from '../../../src/module'

// The signing keys are generated by the test run and passed in through
// `NUXT_OAUTH_SERVER_PRIVATE_KEY`, so no key material lives in the repository.
export default defineNuxtConfig({
  modules: [
    '@nuxthub/core',
    '@frigear-nu/users',
    '@frigear-nu/admin',
    OAuthServerModule,
    // The services' permissions and the fixture's roles (`server/plugins/policy.ts` hands the roles out by email domain).
    (_options: unknown, nuxt: Nuxt) => {
      addPermission(nuxt,
        // Everyone's: what the mobile app asks for.
        { name: 'groups:read', implicit: true },
        { name: 'vouchers:read', implicit: true },
        { name: 'vouchers:write', implicit: true },
        { name: 'shop:order', implicit: true },
        // Everyone holds it, but only staff may hand it to an application (`roleScopes`).
        { name: 'notes:read', label: 'Read your notes', implicit: true },
        // Staff only.
        { name: 'inventory:read' },
        { name: 'inventory:write' },
        { name: 'inventory:manage', sessionOnly: true },
        { name: 'inventory:pii' },
      )
      addRole(nuxt,
        { name: 'user', label: 'User', source: 'host' },
        { name: 'member', label: 'Member', inherit: ['user'], source: 'host' },
        { name: 'staff', label: 'Staff', grant: ['inventory:*', 'inventory:pii', 'oauth:manage'], inherit: ['member'], source: 'host' },
      )
      setDefaultRoles(nuxt, ['user'])
    },
  ],
  runtimeConfig: {
    session: {
      password: 'a-test-only-session-password-at-least-32-chars',
    },
  },
  hub: {
    db: {
      dialect: 'sqlite',
      driver: 'libsql',
      applyMigrationsDuringBuild: false,
    },
  },
  oauthServer: {
    issuer: 'https://id.example.test',
    // Access tokens for every Frigear service: one shared audience, ten minutes.
    accessTokenAudience: 'frigear-services',
    accessTokenTtl: 600,
    scopes: [
      // A named scope: what it stands for, and how the consent screen shows it.
      { name: 'groups', label: 'Your groups', description: 'Which groups you belong to', icon: 'i-lucide-users', permissions: ['groups:read'] },
      // Permission scopes: only how they are presented.
      { name: 'vouchers:read', description: 'See your vouchers', service: 'Vouchers' },
      { name: 'vouchers:write', description: 'Redeem your vouchers', service: 'Vouchers' },
      { name: 'shop:order', description: 'Place orders in the shop', service: 'Shop' },
      { name: 'inventory:read', description: 'See the inventory', service: 'Inventory' },
      { name: 'inventory:write', description: 'Change the inventory', service: 'Inventory' },
    ],
    // `/api/test/` stands in for the host's API; the admin API stays closed.
    cors: { origins: ['capacitor://localhost', 'https://app.example.com'], paths: ['/api/test/'] },
    // A mobile app with a fixed client id, created on first use. The fixture runs in dev, so the dev URI counts.
    clients: [{
      id: 'test-mobile',
      name: 'Test mobile',
      redirectUris: ['com.example.test:/auth/callback'],
      devRedirectUris: ['http://localhost:3001/auth/callback'],
      tags: ['mobile'],
      // Native: kept signed in for six months unused, never longer than a year in all.
      refreshToken: { idleTtl: 60 * 60 * 24 * 180, maxAge: 60 * 60 * 24 * 365 },
    }, {
      // Native only: nothing to open from the user's applications list.
      id: 'test-native',
      name: 'Test native',
      redirectUris: ['com.example.native:/auth/callback'],
    }, {
      // The test turns its row confidential, as if the id had been taken by an application created earlier.
      id: 'test-conflict',
      name: 'Test conflict',
      redirectUris: ['com.example.conflict:/auth/callback'],
    }],
    // The global refresh-token policy is left at its default (30 days idle, no cap).
    settings: {
      pages: { authorize: false, admin: true },
      mcp: true,
      // Everyone may give applications the everyday scopes; only staff anything else.
      roleScopes: {
        user: ['openid', 'profile', 'email', 'groups', 'vouchers:read', 'vouchers:write', 'shop:order', 'oauth:read'],
        staff: ['*'],
      },
    },
  },
})
